<script setup>
import {ref} from 'vue';import {useRouter,useRoute} from 'vue-router';import {useSession} from '../stores/session';
const email=ref(''),password=ref(''),busy=ref(false),error=ref('');const session=useSession(),router=useRouter(),route=useRoute();
async function submit(){busy.value=true;error.value='';try{await session.login(email.value,password.value);router.push('/competitions');}catch(e){error.value=e.message;}finally{busy.value=false;}}
if(route.query.unavailable) error.value='No se pudo comprobar tu sesión. Intenta iniciar sesión nuevamente.';
</script>
<template><div class="login-wrap"><div class="login-panel"><div class="brand"><span class="brand-mark">IR</span><div><strong>INCA RAIL</strong><small>Plataforma interna de fútbol</small></div></div><p class="eyebrow">BIENVENIDO</p><h1>Inicia sesión</h1><p class="sub">Accede al catálogo de competiciones, equipos y jugadores.</p><form @submit.prevent="submit"><label>Correo electrónico<input v-model="email" type="email" autocomplete="username" required placeholder="nombre@empresa.com"/></label><label>Contraseña<input v-model="password" type="password" autocomplete="current-password" required placeholder="••••••••••"/></label><p class="alert" v-if="error||route.query.expired">{{error||"Tu sesión ha caducado. Inicia sesión nuevamente."}}</p><button class="btn primary block" :disabled="busy">{{busy?'Ingresando…':'Entrar a la plataforma →'}}</button></form></div><div class="login-art"><span class="eyebrow">DATOS · EQUIPOS · HISTORIA</span><h2>El fútbol, en una sola vista.</h2><p>Explora competiciones y consulta datos locales aunque el proveedor externo no esté disponible.</p><div class="giant-ball">⚽</div></div></div></template>
